/**
* Filter posts according to selected feed tab
*/
function filterPosts(posts, filter) {
	if (filter === "for-you") return posts;
	if (filter === "friends") return posts.filter((p) => p.author.relationshipState === "friends" || p.author.relationshipState === "self");
	if (filter === "campus") return posts.filter((p) => p.category === "Campus Update" || p.categoryHashtag === "#CampusUpdates" || p.audience === "Campus Only" || p.content.includes("#CampusUpdates"));
	if (filter === "communities") return posts.filter((p) => Boolean(p.communityId) || p.content.includes("#community_") || p.category === "Hostel Life" || p.category === "Academic");
	if (filter === "events") return posts.filter((p) => p.category === "Event" || p.categoryHashtag === "#Event" || p.content.toLowerCase().includes("#event") || p.content.toLowerCase().includes("#campus_event") || p.content.includes("[CAMPUS EVENT]"));
	return posts;
}
/**
* Search users and posts by query term
*/
function searchEntities(query, users, posts) {
	const cleanQuery = query.trim().toLowerCase();
	if (!cleanQuery) return {
		users: [],
		posts: []
	};
	return {
		users: users.filter((u) => {
			return u.name.toLowerCase().includes(cleanQuery) || u.department.toLowerCase().includes(cleanQuery) || u.faculty.toLowerCase().includes(cleanQuery) || u.interests.some((interest) => interest.toLowerCase().includes(cleanQuery));
		}),
		posts: posts.filter((p) => {
			return p.content.toLowerCase().includes(cleanQuery) || p.author.name.toLowerCase().includes(cleanQuery) || p.category.toLowerCase().includes(cleanQuery);
		})
	};
}
/**
* Calculate total unread active notifications count (excludes archived >= 7 days)
*/
function calculateUnreadCount(notifications) {
	return notifications.filter((n) => !n.isRead && !n.isArchived).length;
}
/**
* Validate post submission text
*/
function validatePostSubmission(content) {
	const trimmed = content.trim();
	if (trimmed.length === 0) return {
		valid: false,
		error: "Post content cannot be empty"
	};
	if (trimmed.length > 2e3) return {
		valid: false,
		error: "Post content cannot exceed 2000 characters"
	};
	return { valid: true };
}
/**
* Validate image file selection for post attachment
*/
function validateImageFile(file) {
	const allowedTypes = [
		"image/jpeg",
		"image/jpg",
		"image/png",
		"image/webp",
		"image/gif",
		"image/avif"
	];
	let normalizedType = (file.type || "").toLowerCase().trim();
	if (!normalizedType && file.name) {
		const lower = file.name.toLowerCase();
		if (lower.endsWith(".jpg") || lower.endsWith(".jpeg")) normalizedType = "image/jpeg";
		else if (lower.endsWith(".png")) normalizedType = "image/png";
		else if (lower.endsWith(".webp")) normalizedType = "image/webp";
		else if (lower.endsWith(".gif")) normalizedType = "image/gif";
		else if (lower.endsWith(".avif")) normalizedType = "image/avif";
	}
	if (!allowedTypes.includes(normalizedType)) return {
		valid: false,
		error: "Unsupported image format. Please select a JPEG, PNG, WebP, GIF, or AVIF photo."
	};
	if (file.size > 10485760) return {
		valid: false,
		error: "File size exceeds maximum 10MB limit. Please choose a smaller photo."
	};
	return { valid: true };
}
/**
* Validate video file selection for post attachment (supports MP4, WebM, QuickTime up to 50MB)
*/
function validateVideoFile(file) {
	const allowedVideoTypes = [
		"video/mp4",
		"video/webm",
		"video/quicktime",
		"video/x-m4v",
		"video/ogg",
		"video/mov"
	];
	let normalizedType = (file.type || "").toLowerCase().trim();
	if (!normalizedType && file.name) {
		const lower = file.name.toLowerCase();
		if (lower.endsWith(".mp4") || lower.endsWith(".m4v")) normalizedType = "video/mp4";
		else if (lower.endsWith(".webm")) normalizedType = "video/webm";
		else if (lower.endsWith(".mov")) normalizedType = "video/quicktime";
		else if (lower.endsWith(".ogg")) normalizedType = "video/ogg";
	}
	if (!allowedVideoTypes.includes(normalizedType) && !normalizedType.startsWith("video/")) return {
		valid: false,
		error: "Unsupported video format. Please select an MP4, WebM, or MOV video file."
	};
	if (file.size > 52428800) return {
		valid: false,
		error: "Video file size exceeds maximum 50MB limit."
	};
	return { valid: true };
}
/**
* Validate standard email format (does not restrict to absu.edu.ng)
*/
function validateEmail(email) {
	const trimmed = email.trim();
	return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed);
}
/**
* Validate password strength (minimum 6 characters required by Supabase Auth)
*/
function validatePassword(password) {
	if (password.length < 6) return {
		valid: false,
		error: "Password must be at least 6 characters long."
	};
	return { valid: true };
}
/**
* Validate matching passwords
*/
function validatePasswordMatch(password, confirm) {
	if (password !== confirm) return {
		valid: false,
		error: "Passwords do not match."
	};
	return { valid: true };
}
