async function moderateAdminPost(id, action, reason) {
	try {
		const headers = await getAuthHeader();
		const res = await fetch(`/api/admin/content/posts/${id}/moderate`, {
			method: "POST",
			headers: {
				...headers,
				"Content-Type": "application/json"
			},
			body: JSON.stringify({
				action,
				reason
			})
		}).catch(() => null);
		const json = await parseApiJson(res);
		if (res && json) return json;
		if (action === "hide") {
			const { error } = await supabase.from("posts").update({ visibility: "hidden" }).eq("id", id);
			if (error) return {
				success: false,
				error: error.message || STATIC_ADMIN_UNAVAILABLE_MSG
			};
			return {
				success: true,
				message: "Post hidden from campus feed."
			};
		}
		if (action === "restore") {
			const { error } = await supabase.from("posts").update({ visibility: "public" }).eq("id", id);
			if (error) return {
				success: false,
				error: error.message || STATIC_ADMIN_UNAVAILABLE_MSG
			};
			return {
				success: true,
				message: "Post visibility restored."
			};
		}
		const { error } = await supabase.from("posts").delete().eq("id", id);
		if (error) return {
			success: false,
			error: error.message || STATIC_ADMIN_UNAVAILABLE_MSG
		};
		return {
			success: true,
			message: "Post permanently removed."
		};
	} catch (err) {
		return {
			success: false,
			error: err instanceof Error ? err.message : "Moderation failed"
		};
	}
}
