			const gain2 = ctx.createGain();
			osc2.type = "sine";
			osc2.frequency.setValueAtTime(830.61, now + .12);
			gain2.gain.setValueAtTime(0, now + .12);
			gain2.gain.linearRampToValueAtTime(.22, now + .17);
			gain2.gain.exponentialRampToValueAtTime(.001, now + .65);
			osc2.connect(gain2);
			gain2.connect(ctx.destination);
			osc2.start(now + .12);
			osc2.stop(now + .67);
