/**
* Check permission status using Permissions API where supported.
* Falls back safely to 'prompt' on Safari / older browsers that do not support camera/microphone queries.
*/
async function checkMediaPermission(type) {
	if (typeof navigator === "undefined" || !navigator.mediaDevices?.getUserMedia) return {
		mic: "unsupported",
		camera: "unsupported",
		canDirectlyCall: false
	};
	let micStatus = "prompt";
	let cameraStatus = "prompt";
	try {
		if (navigator.permissions && navigator.permissions.query) micStatus = (await navigator.permissions.query({ name: "microphone" })).state;
	} catch {
		micStatus = "prompt";
	}
	if (type === "video") try {
		if (navigator.permissions && navigator.permissions.query) cameraStatus = (await navigator.permissions.query({ name: "camera" })).state;
	} catch {
		cameraStatus = "prompt";
	}
	else cameraStatus = "granted";
	return {
		mic: micStatus,
		camera: cameraStatus,
		canDirectlyCall: type === "audio" ? micStatus === "granted" : micStatus === "granted" && cameraStatus === "granted"
	};
}
/**
* Checks whether audio input (microphone) or video input (camera) devices exist on the hardware.
*/
async function checkDeviceAvailability() {
	if (typeof navigator === "undefined" || !navigator.mediaDevices?.enumerateDevices) return {
		hasMicrophone: true,
		hasCamera: true
	};
	try {
		const devices = await navigator.mediaDevices.enumerateDevices();
		return {
			hasMicrophone: devices.some((d) => d.kind === "audioinput"),
			hasCamera: devices.some((d) => d.kind === "videoinput")
		};
	} catch {
		return {
			hasMicrophone: true,
			hasCamera: true
		};
	}
}
